-- T007 a T009: configuracion, tipos de servicio, terminos, bitacora y columnas
-- para reportes (Sprint 7, data-model.md, research P-1 a P-13).
-- Aditiva: las columnas nuevas admiten NULL o traen valor por omision, de modo
-- que el codigo del Sprint 6 sigue funcionando contra este esquema. Sin
-- migracion inversa, igual que las anteriores.
-- Orden: primero las tablas nuevas (service_types antes del ALTER de
-- order_services), despues los ALTER y por ultimo los rellenos y la version 1
-- de los terminos.

-- ---------------------------------------------------------------------------
-- Parte 1: tablas nuevas
-- ---------------------------------------------------------------------------

-- settings: pares clave-valor del taller. Nace vacia: si falta una clave rige
-- el valor de respaldo definido en codigo (P-2).
CREATE TABLE IF NOT EXISTS settings (
  setting_key VARCHAR(60) NOT NULL PRIMARY KEY,
  setting_value VARCHAR(200) NOT NULL,
  updated_by INT UNSIGNED NOT NULL,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_settings_user FOREIGN KEY (updated_by)
    REFERENCES users (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- service_types: catalogo de tipos de servicio con intervalo. Sin DELETE
-- (CA-4): se desactiva.
CREATE TABLE IF NOT EXISTS service_types (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  interval_days INT UNSIGNED NULL,
  interval_km INT UNSIGNED NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_by INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_service_types_name (name),
  CONSTRAINT fk_service_types_user FOREIGN KEY (created_by)
    REFERENCES users (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_service_types_interval CHECK (
    (interval_days IS NOT NULL AND interval_days > 0)
    OR (interval_km IS NOT NULL AND interval_km > 0)
  ),
  CONSTRAINT chk_service_types_interval_max CHECK (
    (interval_days IS NULL OR interval_days <= 3650)
    AND (interval_km IS NULL OR interval_km <= 1000000)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- terms_versions: versiones de los terminos y del aviso de privacidad. La
-- vigente es la de mayor version; una version publicada no se edita (FR-032).
CREATE TABLE IF NOT EXISTS terms_versions (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  version INT UNSIGNED NOT NULL,
  terms_text MEDIUMTEXT NOT NULL,
  privacy_text MEDIUMTEXT NOT NULL,
  published_by INT UNSIGNED NULL,
  published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_terms_versions_version (version),
  CONSTRAINT fk_terms_versions_user FOREIGN KEY (published_by)
    REFERENCES users (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- terms_acceptances: constancia de aceptacion. Clave unica (usuario, version)
-- = idempotencia de POST /api/terms/accept. Sin UPDATE ni DELETE.
CREATE TABLE IF NOT EXISTS terms_acceptances (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NOT NULL,
  terms_version_id INT UNSIGNED NOT NULL,
  accepted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_terms_acceptances_user_version (user_id, terms_version_id),
  CONSTRAINT fk_terms_acceptances_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_terms_acceptances_version FOREIGN KEY (terms_version_id)
    REFERENCES terms_versions (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- audit_log: bitacora de acciones sensibles. Solo insercion (P-13). detail se
-- arma con una lista blanca por accion: nunca contrasenas, hashes ni tokens.
CREATE TABLE IF NOT EXISTS audit_log (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NULL,
  actor VARCHAR(100) NOT NULL,
  action VARCHAR(40) NOT NULL,
  entity_type VARCHAR(40) NULL,
  entity_id INT UNSIGNED NULL,
  detail VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_audit_created (created_at),
  KEY idx_audit_user_created (user_id, created_at),
  KEY idx_audit_action_created (action, created_at),
  CONSTRAINT fk_audit_log_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Parte 2: cambios a tablas existentes
-- ---------------------------------------------------------------------------

-- maintenance: NULL en warn_days / warn_km = "usar el valor del taller" (D-16).
-- Se conservan los CHECK >= 0 (un CHECK con NULL no falla).
ALTER TABLE maintenance
  MODIFY COLUMN warn_days INT UNSIGNED NULL,
  MODIFY COLUMN warn_km INT UNSIGNED NULL;

-- order_services: enlace opcional al catalogo de tipos de servicio (D-04).
ALTER TABLE order_services
  ADD COLUMN service_type_id INT UNSIGNED NULL,
  ADD KEY idx_order_services_type (service_type_id),
  ADD CONSTRAINT fk_order_services_type FOREIGN KEY (service_type_id)
    REFERENCES service_types (id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- order_parts: costo congelado por linea (D-05). Tope $99,999.99 como en precios.
ALTER TABLE order_parts
  ADD COLUMN unit_cost DECIMAL(10,2) NULL,
  ADD CONSTRAINT chk_order_parts_unit_cost
    CHECK (unit_cost IS NULL OR (unit_cost >= 0 AND unit_cost <= 99999.99));

-- service_orders: fecha estable de terminacion y marca de aproximacion (D-19).
ALTER TABLE service_orders
  ADD COLUMN finished_at DATETIME NULL,
  ADD COLUMN finished_at_estimated TINYINT(1) NOT NULL DEFAULT 0,
  ADD KEY idx_service_orders_finished_at (finished_at);

-- tickets: instantanea del encabezado del taller y del proximo servicio (D-03).
ALTER TABLE tickets
  ADD COLUMN workshop_name VARCHAR(100) NOT NULL DEFAULT 'Motorix',
  ADD COLUMN workshop_address VARCHAR(200) NULL,
  ADD COLUMN workshop_phone VARCHAR(30) NULL,
  ADD COLUMN next_service_date DATE NULL,
  ADD COLUMN next_service_mileage INT UNSIGNED NULL;

-- users: ultima actividad para el cierre por inactividad en el backend (P-12).
ALTER TABLE users
  ADD COLUMN last_activity_at DATETIME NULL;

-- ---------------------------------------------------------------------------
-- Parte 3: rellenos y version 1 de los terminos
-- ---------------------------------------------------------------------------

-- maintenance: el valor predeterminado historico (30 dias / 500 km) pasa a
-- NULL = "usar el del taller" (P-3). Los valores capturados a mano se conservan.
UPDATE maintenance SET warn_days = NULL WHERE warn_days = 30;
UPDATE maintenance SET warn_km = NULL WHERE warn_km = 500;

-- order_parts: costo con el precio de compra vigente cuando es mayor que 0; el
-- resto queda NULL = "sin costo registrado" (P-8, D-05).
UPDATE order_parts op
  JOIN parts p ON p.id = op.part_id
  SET op.unit_cost = p.purchase_price
  WHERE p.purchase_price > 0;

-- service_orders: las ordenes ya terminadas usan su ultima modificacion como
-- aproximacion y quedan marcadas como estimadas (P-7, D-19).
UPDATE service_orders
  SET finished_at = updated_at, finished_at_estimated = 1
  WHERE status IN ('FINISHED', 'DELIVERED') AND finished_at IS NULL;

-- Version 1 de los terminos: plantilla de instalacion (CA-18). Idempotente.
-- Los textos van como literales hexadecimales UTF-8 para que las tildes
-- sobrevivan al pipe de PowerShell 5.1 con el que se aplican las migraciones.
-- Texto legible: ver specs/007-reportes-configuracion/research.md (P-11) y la
-- pantalla de terminos; cubre los cuatro temas del CA-18.
INSERT INTO terms_versions (version, terms_text, privacy_text, published_by)
SELECT 1,
  CONVERT( USING utf8mb4),
  CONVERT( USING utf8mb4),
  NULL
WHERE NOT EXISTS (SELECT 1 FROM terms_versions WHERE version = 1);
